let iconSequence = 0;
export function renderModelIcon(parent: HTMLElement, vendor: string): void {
  parent.addClass('wesight-vendor-icon');
  const icon = icons[vendor];
  if (!icon) { if (vendor === 'tokendance') parent.setText('T'); else setIcon(parent, 'box'); return; }
  const namespace = 'http://www.w3.org/2000/svg';
  const suffix = `-${++iconSequence}`;
  const svg = document.createElementNS(namespace, 'svg');
  svg.setAttribute('viewBox', icon.viewBox);
  svg.setAttribute('fill', icon.fill);
  svg.setAttribute('aria-hidden', 'true');
  const append = (target: Element, node: IconNode): void => {
    const element = document.createElementNS(namespace, node.tag);
    for (const [key, value] of Object.entries(node.attrs)) {
      element.setAttribute(key, key === 'id' ? value + suffix : value.replace(/url\(#([^)]*)\)/g, `url(#$1${suffix})`));
    }
    for (const child of node.children ?? []) append(element, child);
    target.appendChild(element);
  };
  for (const node of icon.nodes) append(svg, node);
  parent.appendChild(svg);
}
